updateLabelRanks(){
  if(!this.state||!this.state.players)return;
  const sorted=[...this.state.players].sort((a,b)=>{
    const diff=(b.damage||0)-(a.damage||0);
    if(diff!==0)return diff;
    return (a.joinTime||0)-(b.joinTime||0);
  });
  for(let idx=0;idx<sorted.length;idx++){
    const p=sorted[idx],node=this.labelNodes.get(p.username);
    if(node){
      const rank=idx+1,curRank=node.dataset.vipRank;
      if(curRank!==String(rank)){
        node.dataset.vipRank=String(rank);
        if(rank===1){
          node.className="xx-nametag xx-top-1";
          node.innerHTML='<span class="xx-wing-wrap left">'+this.getXianxiaWing("gold")+'</span><div class="xx-card-frame">'+this.getXianxiaCrest("gold")+'<div class="xx-title">【 👑 VÔ THƯỢNG CHÍ TÔN 】</div><div class="xx-player-name">@'+p.username+'</div></div><span class="xx-wing-wrap right">'+this.getXianxiaWing("gold")+'</span>';
        }else if(rank===2){
          node.className="xx-nametag xx-top-2";
          node.innerHTML='<span class="xx-wing-wrap left">'+this.getXianxiaWing("cyan")+'</span><div class="xx-card-frame">'+this.getXianxiaCrest("cyan")+'<div class="xx-title">【 🥈 CỬU THIÊN TIÊN TÔN 】</div><div class="xx-player-name">@'+p.username+'</div></div><span class="xx-wing-wrap right">'+this.getXianxiaWing("cyan")+'</span>';
        }else if(rank===3){
          node.className="xx-nametag xx-top-3";
          node.innerHTML='<span class="xx-wing-wrap left">'+this.getXianxiaWing("ruby")+'</span><div class="xx-card-frame">'+this.getXianxiaCrest("ruby")+'<div class="xx-title">【 🥉 BÁT HOANG ĐẠI NĂNG 】</div><div class="xx-player-name">@'+p.username+'</div></div><span class="xx-wing-wrap right">'+this.getXianxiaWing("ruby")+'</span>';
        }else if(rank<=10){
          node.className="xx-nametag xx-top-elite";
          node.innerHTML='<div class="xx-card-frame"><div class="xx-title">【 ✦ TINH ANH • #'+rank+' 】</div><div class="xx-player-name">@'+p.username+'</div></div>';
        }else{
          node.className="xx-nametag regular";
          node.innerHTML='<span class="xx-player-name">@'+p.username+'</span>';
        }
      }
    }
  }
}
